def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    grid_area = h * w

    # Optimization: Check if any subset of tiles sums to the grid area
    # n <= 7, so 2^7 = 128 subsets
    subset_sums = [0] * (1 << n)
    for mask in range(1, 1 << n):
        # Find least significant set bit
        lsb = mask & (-mask)
        idx = lsb.bit_length() - 1
        prev_mask = mask ^ lsb
        subset_sums[mask] = subset_sums[prev_mask] + tiles[idx][0] * tiles[idx][1]

    valid_masks = [mask for mask in range(1 << n) if subset_sums[mask] == grid_area]
    if not valid_masks:
        return False

    # If grid is empty (h=0 or w=0), check if empty subset is valid
    if grid_area == 0:
        return True

    grid = [[False] * w for _ in range(h)]

    def find_first_empty():
        for r in range(h):
            for c in range(w):
                if not grid[r][c]:
                    return (r, c)
        return None

    def backtrack(target_mask, used_mask):
        pos = find_first_empty()
        if pos is None:
            return True

        r, c = pos

        for i in range(n):
            if not (target_mask & (1 << i)):
                continue
            if used_mask & (1 << i):
                continue

            a, b = tiles[i]
            # Try orientation 1: a x b
            if r + a <= h and c + b <= w:
                valid = True
                for i_off in range(a):
                    for j_off in range(b):
                        if grid[r + i_off][c + j_off]:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    for i_off in range(a):
                        for j_off in range(b):
                            grid[r + i_off][c + j_off] = True
                    if backtrack(target_mask, used_mask | (1 << i)):
                        return True
                    for i_off in range(a):
                        for j_off in range(b):
                            grid[r + i_off][c + j_off] = False

            # Try orientation 2: b x a (if different)
            if a != b:
                if r + b <= h and c + a <= w:
                    valid = True
                    for i_off in range(b):
                        for j_off in range(a):
                            if grid[r + i_off][c + j_off]:
                                valid = False
                                break
                        if not valid:
                            break
                    if valid:
                        for i_off in range(b):
                            for j_off in range(a):
                                grid[r + i_off][c + j_off] = True
                        if backtrack(target_mask, used_mask | (1 << i)):
                            return True
                        for i_off in range(b):
                            for j_off in range(a):
                                grid[r + i_off][c + j_off] = False

        return False

    # Try each valid subset (mask) that sums to grid area
    for mask in valid_masks:
        if backtrack(mask, 0):
            return True

    return False

def count_beautiful_numbers(l: int, r: int) -> int:
    def is_beautiful(n):
        s = 0
        p = 1
        temp = n
        while temp:
            d = temp % 10
            s += d
            p *= d
            temp //= 10
        return s != 0 and p % s == 0

    count = 0
    for i in range(l, r + 1):
        if is_beautiful(i):
            count += 1
    return count

