def min_weight_hamiltonian_walk(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Optional[int]:
    INF = 10**18

    # Step 1: Build graph and compute all-pairs shortest paths
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        u0 = u - 1
        v0 = v - 1
        if w < dist[u0][v0]:
            dist[u0][v0] = w

    # Floyd-Warshall for shortest paths
    for k in range(n):
        for i in range(n):
            if dist[i][k] >= INF:
                continue
            dik = dist[i][k]
            for j in range(n):
                if dist[k][j] < INF:
                    nd = dik + dist[k][j]
                    if nd < dist[i][j]:
                        dist[i][j] = nd

    # Check for negative cycles (should not happen per constraints, but good for safety)
    for i in range(n):
        if dist[i][i] < 0:
            return None

    # Step 2: TSP DP over subsets
    # We need a walk that visits all vertices. Since we can traverse edges multiple times,
    # and we have shortest paths, the problem is equivalent to finding an ordering of the 
    # vertices that minimizes the sum of shortest path distances between consecutive vertices.
    # This is the asymmetric Traveling Salesman Path problem.

    size = 1 << n
    dp = [[INF] * n for _ in range(size)]

    for i in range(n):
        dp[1 << i][i] = 0

    for mask in range(size):
        for last in range(n):
            cur = dp[mask][last]
            if cur >= INF:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                d = dist[last][nxt]
                if d >= INF:
                    continue
                new_mask = mask | (1 << nxt)
                new_cost = cur + d
                if new_cost < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = new_cost

    ans = INF
    full_mask = (1 << n) - 1
    for last in range(n):
        if dp[full_mask][last] < ans:
            ans = dp[full_mask][last]

    if ans >= INF:
        return None
    return ans

from functools import lru_cache

def tic_tac_toe_winner(grid: list[list[int]]) -> str:
    lines = [(0,0,1,0,2,0), (1,0,1,1,1,2), (2,0,2,1,2,2), (0,0,1,1,2,2), (0,2,1,1,2,0), (0,1,1,1,2,1)]
    @lru_cache(maxsize=None)
    def solve(board, turn, sT, sA):
        # board is tuple of 9 (0: empty, 1: T, 2: A)
        for line in lines:
            if all(board[i] == 1 for i in line):
                return True
            if all(board[i] == 2 for i in line):
                return False

        empties = [i for i in range(9) if board[i] == 0]
        if not empties:
            return sT > sA

        if turn == 1:
            max_val = False
            for i in empties:
                nb = list(board)
                nb[i] = 1
                if solve(tuple(nb), 2, sT + grid[i//3][i%3], sA):
                    max_val = True
                    break
            return max_val
        else:
            min_val = True
            for i in empties:
                nb = list(board)
                nb[i] = 2
                if not solve(tuple(nb), 1, sT, sA + grid[i//3][i%3]):
                    min_val = False
                    break
            return min_val

    if solve(tuple([0]*9), 1, 0, 0):
        return "Takahashi"
    else:
        return "Aoki"

def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    inv2 = (MOD + 1) // 2  # Modular inverse of 2 mod MOD
    dp = [0] * (k + 1)
    dp[0] = 1
    for x in nums:
        if x > k:
            continue
        for s in range(k, x - 1, -1):
            dp[s] = (dp[s] + dp[s - x] * inv2) % MOD
    result = dp[k] * pow(2, n, MOD) % MOD
    return result

