def max_production_capacity(n: int, x: int, machines: List[Tuple[int, int, int, int]]) -> int:
    def ceil_div(a, b):
        return (a + b - 1) // b

    # Upper bound for binary search
    high = x * max(max(a, b) for a, p, b, q in machines) // min(min(p, q) for a, p, b, q in machines)
    low = 0
    ans = 0

    def feasible(k):
        total_cost = 0
        for A, P, B, Q in machines:
            min_cost = float('inf')

            # Case 1: Number of S machines (s) is small (0 to B)
            # This covers the case where S is the "preferred" or we are mixing such that
            # we are near the 'boundary' where replacing B S-machines with A T-machines
            # is no longer beneficial (or we run out of S).
            for s in range(B + 1):
                rem = k - s * A
                if rem <= 0:
                    t = 0
                else:
                    t = ceil_div(rem, B)
                cost = s * P + t * Q
                if cost < min_cost:
                    min_cost = cost
                    if min_cost > x - total_cost: # Early stop if already over budget
                        break

            # Case 2: Number of T machines (t) is small (0 to A)
            # Symmetric case.
            for t in range(A + 1):
                rem = k - t * B
                if rem <= 0:
                    s = 0
                else:
                    s = ceil_div(rem, A)
                cost = s * P + t * Q
                if cost < min_cost:
                    min_cost = cost
                    if min_cost > x - total_cost: # Early stop if already over budget
                        break

            total_cost += min_cost
            if total_cost > x:
                return False
        return True

    while low <= high:
        mid = (low + high) // 2
        if feasible(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1
    return ans

