def max_1122_subarray_length(n: int, a: List[int]) -> int:
    if n < 2:
        return 0

    def calc(arr):
        best = 0
        start = 0
        seen = {}
        for i, val in enumerate(arr):
            if val == 0:
                start = i + 1
                seen.clear()
                continue
            if val in seen:
                start = max(start, seen[val] + 1)
            seen[val] = i
            current_len = i - start + 1
            if current_len > best:
                best = current_len
        return best * 2

    even_pairs = []
    for i in range(0, n - 1, 2):
        if a[i] == a[i + 1]:
            even_pairs.append(a[i])
        else:
            even_pairs.append(0)

    odd_pairs = []
    for i in range(1, n - 1, 2):
        if a[i] == a[i + 1]:
            odd_pairs.append(a[i])
        else:
            odd_pairs.append(0)

    return max(calc(even_pairs), calc(odd_pairs))

