def count_good_string_replacements(n: int, k: int, s: str) -> int:
    MOD = 998244353

    # Optimization: Early exit if k is 0 (all replacements are valid) 
    # or if k exceeds the maximum possible number of substrings.
    max_substrings = n * (n + 1) // 2
    if k == 0:
        # Each '?' can be replaced in 3 ways
        num_q = s.count('?')
        return (3 ** num_q) % MOD
    if k > max_substrings:
        return 0

    # A string is "good" iff it has even length and counts of 'A', 'B', 'C' are even.
    # This is equivalent to the prefix parity hash being identical at the start and end of the substring.
    # Hash h[i] = (prefixA[i] % 2, prefixB[i] % 2, i % 2)
    # Substring s[t..i-1] is good iff h[t] == h[i].

    def get_hash(a, b, p):
        return (a << 2) | (b << 1) | p

    def transition(h, ch):
        a = (h >> 2) & 1
        b = (h >> 1) & 1
        p = h & 1
        if ch == 'A':
            a = 1 - a
        elif ch == 'B':
            b = 1 - b
        # p always flips
        p = 1 - p
        return get_hash(a, b, p)

    # DP state: (j, h_curr, c_tuple)
    # j: count of good substrings so far
    # h_curr: hash at the current end of the prefix (h[pos])
    # c_tuple: tuple of counts of each hash value seen so far in h[0..pos]

    init_h = get_hash(0, 0, 0)
    init_c = [0] * 8
    init_c[init_h] = 1

    dp = {(0, init_h, tuple(init_c)): 1}

    for pos in range(n):
        dp_next = {}
        if s[pos] == '?':
            chars = ['A', 'B', 'C']
        else:
            chars = [s[pos]]

        for state, ways in dp.items():
            j, h_curr, c_tuple = state
            for ch in chars:
                h_next = transition(h_curr, ch)
                inc = c_tuple[h_next]
                j_new = j + inc
                if j_new > k:
                    continue

                c_list = list(c_tuple)
                c_list[h_next] += 1
                c_new = tuple(c_list)

                next_state = (j_new, h_next, c_new)
                dp_next[next_state] = (dp_next.get(next_state, 0) + ways) % MOD

        dp = dp_next
        if not dp:
            break

    result = 0
    for state, ways in dp.items():
        if state[0] >= k:
            result = (result + ways) % MOD

    return result

