def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    def f2(X, Y):
        if Y < 0:
            X, Y = Y, X
        if X < 0:
            X, Y = -Y, -X
        return X * X + Y * Y + 2 * X + 2 * Y

    return f2(C, D) - f2(A, D) - f2(C, B) + f2(A, B)

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s == t:
        return 0
    if s.count('B') != t.count('B'):
        return -1

    from collections import deque

    start = s + 'EE'
    target = t + 'EE'

    if start == target:
        return 0

    visited = set()
    visited.add(start)
    q = deque()
    q.append((start, 0))

    while q:
        state, dist = q.popleft()

        e1, e2 = -1, -1
        for idx in range(len(state)):
            if state[idx] == 'E':
                if e1 == -1:
                    e1 = idx
                else:
                    e2 = idx
                    break

        dest1, dest2 = sorted([e1, e2])

        for i in range(len(state) - 1):
            if state[i] in ('B', 'W') and state[i + 1] in ('B', 'W'):
                new_state_list = list(state)
                stone1 = state[i]
                stone2 = state[i + 1]

                new_state_list[i] = 'E'
                new_state_list[i + 1] = 'E'
                new_state_list[dest1] = stone1
                new_state_list[dest2] = stone2

                new_state = ''.join(new_state_list)

                if new_state not in visited:
                    if new_state == target:
                        return dist + 1
                    visited.add(new_state)
                    q.append((new_state, dist + 1))

    return -1

def count_good_sequences(N: int, M: int) -> int:
    MOD = 998244353

    def power_mod(base, exp, mod):
        result = 1
        base = base % mod
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp //= 2
        return result

    if N <= 1:
        return 0
    if M == 1:
        return 1

    return (2 ** (M + 1) - 2) % MOD

