def min_operations_to_match_grids(H: int, W: int, A: List[List[int]], B: List[List[int]]) -> Optional[int]:
    def inversion_count(perm: List[int]) -> int:
        count = 0
        n = len(perm)
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    count += 1
        return count

    # Check if the multiset of elements in A and B are the same
    if sorted([x for row in A for x in row]) != sorted([x for row in B for x in row]):
        return None

    best = None
    for row_perm in permutations(range(H)):
        for col_perm in permutations(range(W)):
            # Check if A[row_perm[i]][col_perm[j]] == B[i][j] for all i, j
            valid = True
            for i in range(H):
                for j in range(W):
                    if A[row_perm[i]][col_perm[j]] != B[i][j]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                cost = inversion_count(list(row_perm)) + inversion_count(list(col_perm))
                if best is None or cost < best:
                    best = cost

    return best

