def max_subsequence_value(nums: List[int], k: int) -> int:
    if k == 0:
        return 0
    n = len(nums)
    # pre[i] = set of bitmasks obtainable as the OR of any k elements
    #           chosen from nums[0:i] (indices 0..i-1)
    # suf[i] = set of bitmasks obtainable as the OR of any k elements
    #           chosen from nums[i:n] (indices i..n-1)
    pre = [set() for _ in range(n + 1)]
    suf = [set() for _ in range(n + 1)]
    pre[0] = {0}
    suf[n] = {0}

    for i in range(1, n + 1):
        pre[i] = set(pre[i - 1])
        for v in pre[i - 1]:
            pre[i].add(v | nums[i - 1])

    for i in range(n - 1, -1, -1):
        suf[i] = set(suf[i + 1])
        for v in suf[i + 1]:
            suf[i].add(v | nums[i])

    best = 0
    # The subsequence is formed by picking k elements from the left part
    # (indices < i) and k elements from the right part (indices >= i).
    # The boundary i can range from 0 to n, but for exactly 2*k elements
    # to be pickable, we need i >= k and n - i >= k.
    for i in range(k, n - k + 1):
        for a in pre[i]:
            for b in suf[i]:
                val = a ^ b
                if val > best:
                    best = val
    return best

