def count_subsequence_pairs(nums: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    if n < 2:
        return 0

    max_val = 200

    dp = {}
    for val in nums:
        new_dp = dict(dp)
        for state, ways in dp.items():
            g, c, m = state
            new_g = gcd(g, val)
            new_c = c + 1
            new_m = min(m, val)
            new_state = (new_g, new_c, new_m)
            new_dp[new_state] = (new_dp.get(new_state, 0) + ways) % MOD

        new_state_single = (val, 1, val)
        new_dp[new_state_single] = (new_dp.get(new_state_single, 0) + 1) % MOD

        dp = new_dp

    sum_by_gcd_min = {}
    for (g, c, m), ways in dp.items():
        if c >= 2:
            sum_by_gcd_min[(g, m)] = (sum_by_gcd_min.get((g, m), 0) + ways) % MOD

    ans = 0
    for (g, m1), c1 in sum_by_gcd_min.items():
        for m2 in range(m1 + 1, max_val + 1):
            c2 = sum_by_gcd_min.get((g, m2), 0)
            ans = (ans + c1 * c2) % MOD

    for m in range(1, max_val + 1):
        c = sum_by_gcd_min.get((1, m), 0)
        ans = (ans + c * (c - 1) // 2) % MOD

    return ans

