def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    total_cells = h * w
    full_mask = (1 << total_cells) - 1

    def solve(mask: int, used_mask: int, remaining_area: int) -> bool:
        if mask == full_mask:
            return True

        # Find the first empty cell
        target = None
        for r in range(h):
            for c in range(w):
                idx = r * w + c
                if not (mask & (1 << idx)):
                    target = (r, c)
                    break
            if target is not None:
                break

        if target is None:
            return True

        r0, c0 = target
        empty_cells = total_cells - bin(mask).count('1')

        for i in range(n):
            if used_mask & (1 << i):
                continue
            a, b = tiles[i]
            area = a * b

            # Optimization: If remaining area minus this tile's area is less than empty cells
            # minus this tile's area, it's not enough. i.e. remaining_area < empty_cells.
            # But we check remaining_area >= empty_cells at the start of the call.
            # So we just recurse.

            # Orientation 1: a x b
            if r0 + a <= h and c0 + b <= w:
                valid = True
                block_mask = 0
                for dr in range(a):
                    for dc in range(b):
                        r, c = r0 + dr, c0 + dc
                        idx = r * w + c
                        cell_bit = 1 << idx
                        if mask & cell_bit:
                            valid = False
                            break
                        block_mask |= cell_bit
                    if not valid:
                        break
                if valid:
                    if solve(mask | block_mask, used_mask | (1 << i), remaining_area - area):
                        return True

            # Orientation 2: b x a (if different)
            if a != b:
                if r0 + b <= h and c0 + a <= w:
                    valid = True
                    block_mask = 0
                    for dr in range(b):
                        for dc in range(a):
                            r, c = r0 + dr, c0 + dc
                            idx = r * w + c
                            cell_bit = 1 << idx
                            if mask & cell_bit:
                                valid = False
                                break
                            block_mask |= cell_bit
                        if not valid:
                            break
                    if valid:
                        if solve(mask | block_mask, used_mask | (1 << i), remaining_area - area):
                            return True

        return False

    total_area = sum(a * b for a, b in tiles)
    if total_area < total_cells:
        return False

    return solve(0, 0, total_area)

def sum_of_scores(n: int, m: int) -> int:
    MOD = 998244353

    if m == 1:
        return n % MOD

    # Precompute sigma^k(d) for d=1..m and k=0..2
    # sigma^k(d) = sum_{j|d} j^k
    sigma = [[1] * (m + 1) for _ in range(3)]
    for k in range(3):
        for j in range(1, m + 1):
            base = pow(j, k, MOD)
            for multiple in range(j, m + 1, j):
                sigma[k][multiple] = (sigma[k][multiple] + base) % MOD

    # Transition matrix T of size m x m
    # T[i-1][j-1] = sum_{d | g} sigma^1(g) * sigma^1(i/d) * sigma^0(j/d)
    # where g = i // d
    T = [[0] * m for _ in range(m)]
    for i in range(1, m + 1):
        for j in range(1, m + 1):
            s = 0
            for d in range(1, min(i, j) + 1):
                if i % d == 0 and j % d == 0:
                    g = i // d
                    rem_j = j // d
                    # term = sigma^1(g) * sigma^1(d) * sigma^0(rem_j)
                    term = (sigma[1][g] * sigma[1][d]) % MOD
                    term = (term * sigma[0][rem_j]) % MOD
                    s = (s + term) % MOD
            T[i - 1][j - 1] = s

    # Vector v0 of length m
    # v0[i-1] = sigma^1(i+1) * sigma^1(1) * sigma^0(1) = sigma^1(i+1)
    v0 = [0] * m
    for i in range(m):
        v0[i] = sigma[1][i + 1]

    def mat_vec_mul(A, v):
        return [sum(A[i][j] * v[j] for j in range(len(v))) % MOD for i in range(len(A))]

    def mat_mul(A, B):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k]:
                    aik = A[i][k]
                    for j in range(n):
                        C[i][j] = (C[i][j] + aik * B[k][j]) % MOD
        return C

    def mat_pow(M, p):
        n = len(M)
        R = [[int(i == j) for j in range(n)] for i in range(n)]
        base = M
        while p > 0:
            if p & 1:
                R = mat_mul(R, base)
            base = mat_mul(base, base)
            p >>= 1
        return R

    # We need S_n = sum_{l=1}^n v_{l-1}^T * T^{l-1}
    # Construct augmented matrix M' of size (m+1)x(m+1)
    M_prime = [[0] * (m + 1) for _ in range(m + 1)]
    # Top-left: T
    for i in range(m):
        for j in range(m):
            M_prime[i][j] = T[i][j]
    # Top-right: v0
    for i in range(m):
        M_prime[i][m] = v0[i]
    # Bottom-left: ones
    for j in range(m):
        M_prime[m][j] = 1
    # Bottom-right: 0

    MP = mat_pow(M_prime, n)

    # The sum is the last element of the bottom row of MP (index [m][m])
    result = MP[m][m]

    return result % MOD

