def _check_win(state):
    """Return 1 if Takahashi (1) wins, -1 if Aoki (-1) wins, 0 if no win."""
    for i, j, k in LINES:
        if state[i] != 0 and state[i] == state[j] and state[i] == state[k]:
            return state[i]
    return 0

def _is_full(state):
    return all(cell != 0 for cell in state)

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    flat = [grid[i][j] for i in range(3) for j in range(3)]

    memo = {}

    def solve(state, turn):
        # turn: 1 for Takahashi, -1 for Aoki
        key = (tuple(state), turn)
        if key in memo:
            return memo[key]

        win = _check_win(state)
        if win != 0:
            memo[key] = win
            return win

        if _is_full(state):
            t_score = sum(flat[i] for i in range(9) if state[i] == 1)
            a_score = sum(flat[i] for i in range(9) if state[i] == -1)
            res = 1 if t_score > a_score else -1
            memo[key] = res
            return res

        best = None
        for i in range(9):
            if state[i] == 0:
                state[i] = turn
                res = solve(state, -turn)
                state[i] = 0
                if best is None:
                    best = res
                elif turn == 1 and res == 1:
                    best = 1
                    break
                elif turn == -1 and res == -1:
                    best = -1
                    break

        memo[key] = best
        return best

    result = solve([0] * 9, 1)
    return "Takahashi" if result == 1 else "Aoki"

def can_transform(k: int, s: str, t: str) -> bool:
    if k < 0:
        return s == t
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    INF = float('inf')
    prev = {j: j for j in range(min(m, k) + 1)}
    for i in range(1, n + 1):
        curr = {}
        L = max(0, i - k)
        R = min(m, i + k)
        for j in range(L, R + 1):
            cost = INF
            if j in prev:
                cost = min(cost, prev[j] + 1)
            if j - 1 in curr:
                cost = min(cost, curr[j - 1] + 1)
            if j - 1 in prev:
                replace_cost = 0 if s[i - 1] == t[j - 1] else 1
                cost = min(cost, prev[j - 1] + replace_cost)
            curr[j] = cost
        prev = curr
    return m in prev and prev[m] <= k

