def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    MOD = 998244353

    @functools.lru_cache(maxsize=None)
    def dp(n_rem, i):
        # n_rem: number of characters remaining to place
        # i: next index in X to match (0 to M)
        if n_rem == 0:
            return 1

        ans = 0
        # Sum over possible next character c
        for c in range(1, K + 1):
            if c == X[i]:
                # This character matches X[i], so we advance to i+1
                ans += dp(n_rem - 1, i + 1)
            else:
                # This character does not match X[i]
                ans += dp(n_rem - 1, i)

        return ans % MOD

    return dp(N, 0)

def min_longest_substring(s: str, numOps: int) -> int:
    n = len(s)
    if n == 0:
        return 0

    # Get runs of identical characters
    runs = []
    cur_len = 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            cur_len += 1
        else:
            runs.append(cur_len)
            cur_len = 1
    runs.append(cur_len)

    # Check if it is possible to achieve maximum run length <= L using at most numOps flips
    def can_achieve(L):
        if L == 0:
            return False

        total_flips = 0
        for r in runs:
            if r > L:
                # Number of flips needed in this run is r // (L + 1)
                total_flips += r // (L + 1)
                if total_flips > numOps:
                    return False
        return True

    # Binary search for the minimum possible longest run length
    lo = 1
    hi = n

    while lo < hi:
        mid = (lo + hi) // 2
        if can_achieve(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo

